package com.printflow.customer;

import com.printflow.files.*;import com.printflow.identity.*;import com.printflow.shared.RequestLimits;
import java.io.*;import java.util.*;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.transaction.support.*;import org.springframework.web.server.ResponseStatusException;

@Service public class DeliveryPhotos {
 public record Image(InputStream stream,long size,String mime){}
 private final JdbcTemplate db;private final ArtifactStorage store;private final MalwareScanner scanner;private final ProjectNotifications mail;private final RequestLimits limits;
 public DeliveryPhotos(JdbcTemplate db,ArtifactStorage store,MalwareScanner scanner,ProjectNotifications mail,RequestLimits limits){this.db=db;this.store=store;this.scanner=scanner;this.mail=mail;this.limits=limits;}
 private ResponseStatusException conflict(String text){return new ResponseStatusException(HttpStatus.CONFLICT,text);}
 private Map<String,Object> scope(StaffPrincipal u,UUID id,boolean write){
  var rows=db.queryForList("select e.status,f.state as work_state,f.photos_required from enquiries e join fulfilment_work f on f.enquiry_id=e.id where e.id=? and (? or (?='CUSTOMER' and e.customer_user_id=?) or (?='SALES' and e.assigned_staff_id=?) or (?='DESIGNER' and e.designer_id=?) or (?='OPERATOR' and exists(select 1 from production_jobs j where j.enquiry_id=e.id and j.operator_id=?)) or (?='DELIVERY' and exists(select 1 from staff_job_tasks j where j.enquiry_id=e.id and j.staff_id=? and j.job_role='DELIVERY')))"+(write?" for update of e":""),id,u.role().equals("OWNER"),u.role(),u.id(),u.role(),u.id(),u.role(),u.id(),u.role(),u.id(),u.role(),u.id());
  if(rows.isEmpty())throw new NoSuchElementException();var e=rows.getFirst();if(write){if(!Set.of("OWNER","DELIVERY").contains(u.role()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);if("CLOSED".equals(e.get("status")))throw conflict("Closed work is read-only");}return e;
 }
 public Map<String,Object> list(StaffPrincipal u,UUID id){var e=scope(u,id,false);return Map.of("required",e.get("photos_required"),"canUpload",!"CLOSED".equals(e.get("status"))&&Set.of("OWNER","DELIVERY").contains(u.role())&&Set.of("READY","IN_TRANSIT","DELIVERED").contains(e.get("work_state")),"owner",u.role().equals("OWNER"),"workState",e.get("work_state"),"photos",db.queryForList("select id,stage,caption,display_name,media_type,byte_size,state,scan_engine,created_at from delivery_photos where enquiry_id=? and (? or state='CLEAN') order by created_at,id limit 30",id,!u.role().equals("CUSTOMER")));}
 @Transactional(timeout=75,rollbackFor=Exception.class) public Map<String,Object> upload(StaffPrincipal u,UUID id,String stage,String name,String mime,String caption,InputStream input)throws IOException{
  var e=scope(u,id,true);if(!Set.of("PICKUP","TRANSIT","DELIVERY").contains(stage))throw new IllegalArgumentException("Choose pickup, transit or delivery");
  String work=e.get("work_state").toString();boolean allowed=stage.equals("PICKUP")?Set.of("READY","IN_TRANSIT").contains(work):stage.equals("TRANSIT")?work.equals("IN_TRANSIT"):Set.of("IN_TRANSIT","DELIVERED").contains(work);if(!allowed)throw conflict("This photo belongs to a later or completed delivery stage");
  if(name==null||name.isBlank()||name.length()>180||!Set.of("image/png","image/jpeg").contains(mime)||caption==null||caption.trim().length()<5||caption.length()>500)throw new IllegalArgumentException("Choose a PNG/JPEG and a caption of 5–500 characters");
  limits.require("delivery-photo",u.id().toString(),30);
  if(db.queryForObject("select count(*) from delivery_photos where enquiry_id=?",Integer.class,id)>=30||db.queryForObject("select coalesce(sum(byte_size),0) from delivery_photos where enquiry_id=?",Long.class,id)>=95L*1024*1024)throw conflict("Delivery photo allowance reached");
  var file=store.write(input);TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){@Override public void afterCompletion(int status){if(status!=STATUS_COMMITTED)try{store.discard(file.id());}catch(IOException ignored){}}});
  if(file.size()>5L*1024*1024)throw new ResponseStatusException(HttpStatus.PAYLOAD_TOO_LARGE,"Photo must be at most 5 MiB");ArtifactPolicy.inspect(name,mime,file.size(),store.prefix(file.id()));var verdict=scanner.scan(store.path(file.id()));if(verdict.state()==ArtifactPolicy.State.CLEAN)try(var verified=store.verified(file.id(),file.size(),file.hash())){}
  db.update("insert into delivery_photos(id,enquiry_id,uploaded_by,stage,caption,display_name,media_type,byte_size,sha256,state,scan_engine,scanned_at) values(?,?,?,?,?,?,?,?,?,?,?,case when ?='QUARANTINED' then null else now() end)",file.id(),id,u.id(),stage,caption.trim(),name,mime,file.size(),file.hash(),verdict.state().name(),verdict.engine(),verdict.state().name());
  if(verdict.state()==ArtifactPolicy.State.CLEAN)notifyPhoto(id,file.id(),u.id(),stage,caption.trim());return list(u,id);
 }
 @Transactional(timeout=75,rollbackFor=Exception.class) public Map<String,Object> rescan(StaffPrincipal u,UUID id,UUID photo)throws IOException{scope(u,id,true);limits.require("delivery-scan",u.id().toString(),20);var row=photo(id,photo);var verdict=scanner.scan(store.path(photo));if(verdict.state()==ArtifactPolicy.State.CLEAN)try(var verified=store.verified(photo,((Number)row.get("byte_size")).longValue(),row.get("sha256").toString())){}db.update("update delivery_photos set state=?,scan_engine=?,scanned_at=case when ?='QUARANTINED' then null else now() end where id=?",verdict.state().name(),verdict.engine(),verdict.state().name(),photo);if(verdict.state()==ArtifactPolicy.State.CLEAN)notifyPhoto(id,photo,u.id(),row.get("stage").toString(),row.get("caption").toString());return list(u,id);}
 private Map<String,Object> photo(UUID id,UUID photo){var rows=db.queryForList("select * from delivery_photos where id=? and enquiry_id=?",photo,id);if(rows.isEmpty())throw new NoSuchElementException();return rows.getFirst();}
 @Transactional(readOnly=true) public Image preview(StaffPrincipal u,UUID id,UUID photo)throws IOException{scope(u,id,false);var row=photo(id,photo);if(!"CLEAN".equals(row.get("state")))throw conflict("Photo has not passed scanning");long size=((Number)row.get("byte_size")).longValue();try{return new Image(store.verified(photo,size,row.get("sha256").toString()),size,row.get("media_type").toString());}catch(IOException broken){throw conflict("Photo integrity check failed");}}
 public void require(UUID id,String stage)throws IOException{if(!db.queryForObject("select photos_required from fulfilment_work where enquiry_id=?",Boolean.class,id))return;var rows=db.queryForList("select id,byte_size,sha256 from delivery_photos where enquiry_id=? and stage=? and state='CLEAN' order by created_at desc limit 1",id,stage);if(rows.isEmpty())throw conflict("Add a scanned "+stage.toLowerCase(Locale.ROOT)+" photo before confirming this milestone, or ask the owner to record an evidence exception before dispatch");var row=rows.getFirst();try(var verified=store.verified((UUID)row.get("id"),((Number)row.get("byte_size")).longValue(),row.get("sha256").toString())){}catch(IOException broken){throw conflict("Delivery evidence integrity check failed");}}
 @Transactional public Map<String,Object> policy(StaffPrincipal u,UUID id,boolean required,String note){var e=scope(u,id,true);if(!u.role().equals("OWNER"))throw new ResponseStatusException(HttpStatus.FORBIDDEN);if(!Set.of("PRODUCTION","READY").contains(e.get("work_state")))throw conflict("Set photo requirements before dispatch");if(note==null||note.trim().length()<10||note.length()>500)throw new IllegalArgumentException("Explain the customer-visible evidence agreement");db.update("update fulfilment_work set photos_required=?,revision=revision+1,updated_at=now() where enquiry_id=?",required,id);UUID event=UUID.randomUUID();String text="Delivery photos "+(required?"required":"waived by owner")+": "+note.trim();db.update("insert into work_events(id,enquiry_id,actor_id,kind,message) values(?,?,?,'PHOTO_POLICY',?)",event,id,u.id(),text);mail.both(id,"DELIVERY_PHOTO",event,text);return list(u,id);}
 private void notifyPhoto(UUID id,UUID photo,UUID actor,String stage,String caption){String text=stage.toLowerCase(Locale.ROOT)+" photo added: "+caption+". View the private photo in your project workspace.";if(db.update("insert into work_events(id,enquiry_id,actor_id,kind,message) values(?,?,?,'DELIVERY_PHOTO',?) on conflict do nothing",photo,id,actor,text)==1)mail.both(id,"DELIVERY_PHOTO",photo,text);}
}
